style.css:
@-moz-document domain("youtube.com") {
/* --- 1. Reemplazar el punto rojo/cabezal de la barra de progreso por el Caballero --- */
    .ytp-scrubber-button {
        background: url('https://i.imgur.com/8Q0N94E.png') no-repeat center center !important;
        background-size: contain !important;
        width: 32px !important;
        height: 32px !important;
        border: none !important;
        border-radius: 0 !important;
        box-shadow: none !important;
        transform: scale(1.3) translateY(-4px) !important;
    }

    /* Ocultar el punto rojo predeterminado */
    .ytp-scrubber-container {
        top: -10px !important;
    }

    /* --- 2. Color de la barra de progreso (Azul oscuro / Morado de Hollow Knight) --- */
    .ytp-play-progress.ytp-swatch-background-color {
        background-color: #2b3252 !important;
    }

    /* Color de la barra cuando pasas el cursor */
    .ytp-hover-progress {
        background-color: rgba(255, 255, 255, 0.2) !important;
    }

    /* --- 3. Personalizar la barra cargada (buffer) --- */
    .ytp-load-progress {
        background-color: rgba(255, 255, 255, 0.4) !important;
    }

    /* --- 4. Opcional: Cambiar el cursor a la aguijón (Nail) de Hollow Knight --- */
    body, a, button, .ytp-button {
        cursor: url('https://cur.cursors-4u.net/games/gam-13/gam1282.cur'), auto !important;
    }
}
